import { test, expect } from '@playwright/test';

test.describe('Checkboxes functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
  });

  test('Initial checkbox states', async ({ page }) => {
    const firstCheckbox = page.getByLabel('Checkbox 1');
    const secondCheckbox = page.getByLabel('Checkbox 2');

    await expect(firstCheckbox).not.toBeChecked();
    await expect(secondCheckbox).toBeChecked();
  });

  test('Toggle checkboxes', async ({ page }) => {
    const firstCheckbox = page.getByLabel('Checkbox 1');
    const secondCheckbox = page.getByLabel('Checkbox 2');

    await firstCheckbox.check();
    await expect(firstCheckbox).toBeChecked();
    await expect(secondCheckbox).toBeChecked();

    await secondCheckbox.uncheck();
    await expect(firstCheckbox).toBeChecked();
    await expect(secondCheckbox).not.toBeChecked();
  });
});
